-- Values are the Excel cached values (data_only), NOT formulas.
-- Table profilkes_indicators is created by Batch 1 seed; this file only INSERTs.
-- Excel errors (#DIV/0!, #REF!) are seeded as NULL with data_quality_flag='source_error'.
-- Rasio rows whose value deviates >25% from total/704243*1000 (e.g. Tabel 13
-- dokter 4.9 vs 0.52 yang dihitung, Tabel 17 biomedika 2428.2 vs 0.31) are
-- seeded as-is with data_quality_flag='ratio_mismatch_needs_confirmation'
-- (Batch 1 default rule: show as-is + flag). Tabel 15 has no rasio values
-- in the source, so none seeded.
-- Idempotent: ON DUPLICATE KEY UPDATE, unique key (report_year, source_table, metric_code, region_name).
-- 2026-11-25 fix: Batch 1 created section as VARCHAR(10) (only Roman numerals
-- I-VII were stored then), but Batch 2 stores facility-category labels here:
-- 'RUMAH SAKIT' (11 chars) and 'SARANA LAINNYA' (14). Without the ALTER below,
-- seeding failed with ERROR 1406 (22001) Data too long for column 'section'
-- at row 169 (first RUMAH SAKIT row). The ALTER runs before the transaction
-- (ALTER cannot run inside one) and is safe to repeat.

ALTER TABLE profilkes_indicators MODIFY COLUMN section VARCHAR(50) NULL;

